"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Step 0 items 8-9 (P1 v0.3, section 4): seeded splits of voices, rooms and background noise.

- Kokoro v1.0 English voices (28): stratified by accent and gender into train 15 / dev 5 / test 8. The replication
  set reuses the test voices. Family voices are drawn from the same split, never the user's own voice.
- Piper en_US-libritts-high speakers (904, the unseen second engine): 40 for test and 20 for replication.
- Rooms: RIRS_NOISES simulated small and medium rooms (200 each, 100 RIRs per room), split by room, stratified by size:
  train 60%, dev 15%, test 25%; replication reuses test rooms. Real RIRs are not used, because their room labels are
  inconsistent (single-RIR "rooms", binaural variants of one room).
- Noise: DEMAND 16 kHz channel 1, 17 environments split by environment: test 4, dev 3, train 10 (seeded); replication
  reuses test environments.
usage: python -I scripts/step0_split_aux.py <output json>
"""
import json
import os
import random
import sys

SEED = 20261113
KOKORO = {
    "af": ["af_heart", "af_alloy", "af_aoede", "af_bella", "af_jessica", "af_kore", "af_nicole", "af_nova",
           "af_river", "af_sarah", "af_sky"],
    "am": ["am_adam", "am_echo", "am_eric", "am_fenrir", "am_liam", "am_michael", "am_onyx", "am_puck", "am_santa"],
    "bf": ["bf_alice", "bf_emma", "bf_isabella", "bf_lily"],
    "bm": ["bm_daniel", "bm_fable", "bm_george", "bm_lewis"],
}
VOICE_PLAN = {"af": (6, 2, 3), "am": (5, 1, 3), "bf": (2, 1, 1), "bm": (2, 1, 1)}
RIR_ROOT = "data/rirs_x/RIRS_NOISES/simulated_rirs"
DEMAND = "data/demand_x"


def main(out_path):
    rng = random.Random(SEED)
    voices = {"train": [], "dev": [], "test": []}
    for group, (a, b, c) in VOICE_PLAN.items():
        v = KOKORO[group][:]
        rng.shuffle(v)
        voices["train"] += v[:a]
        voices["dev"] += v[a:a + b]
        voices["test"] += v[a + b:a + b + c]
    piper = list(range(904))
    rng.shuffle(piper)
    rooms = {"train": [], "dev": [], "test": []}
    for size in ("smallroom", "mediumroom"):
        ids = sorted({line.split()[3] for line in open(os.path.join(RIR_ROOT, size, "rir_list"))})
        rng.shuffle(ids)
        n = len(ids)
        rooms["train"] += ids[:int(0.60 * n)]
        rooms["dev"] += ids[int(0.60 * n):int(0.75 * n)]
        rooms["test"] += ids[int(0.75 * n):]
    envs = sorted(os.listdir(DEMAND))
    rng.shuffle(envs)
    noise = {"test": envs[:4], "dev": envs[4:7], "train": envs[7:]}
    out = {"seed": SEED, "voices": voices, "piper_speakers": {"test": piper[:40], "replication": piper[40:60]},
           "rooms": rooms, "noise_envs": noise,
           "note": "replication reuses the test voices, rooms and noise environments"}
    json.dump(out, open(out_path, "w"), indent=1)
    print({k: len(v) for k, v in voices.items()}, voices["test"])
    print({k: len(v) for k, v in rooms.items()}, "| noise", noise)


if __name__ == "__main__":
    main(sys.argv[1])
